-- Giorno 12: ciclo del tritone crestato. Richiede 003_first_six_games.sql.
begin;
update calendar_private.calendar_days set challenge='{"type":"sequence","placeholder":false,"version":"bisana-newt-cycle-v1","title":"Come cresce il tritone crestato?","instructions":"Metti in ordine le quattro fasi del ciclo del tritone crestato, iniziando dall’uovo. Usa le frecce per spostare le carte, poi conferma.","items":["Uovo","Larva","Giovane","Adulto"],"images":["images/giochi/tritone-fase-0.png","images/giochi/tritone-fase-1.png","images/giochi/tritone-fase-2.png","images/giochi/tritone-fase-3.png"],"solution":[0,1,2,3],"cycle_label":"Ciclo del tritone crestato in ordine","hint":"La larva vive in acqua e ha branchie esterne ai lati della testa. Il giovane ha già perso le branchie. La cresta del disegno appartiene a un maschio adulto nel periodo riproduttivo.","explanation":"L’ordine corretto è uovo → larva → giovane → adulto. Il tritone crestato italiano (Triturus carnifex) è un anfibio: il suo ciclo comprende una fase acquatica e una vita anche sulla terraferma.\n\nLa femmina depone le uova una alla volta, avvolgendole nelle foglie delle piante acquatiche. Dall’uovo esce una larva che vive nell’acqua e respira con branchie esterne, riconoscibili come piccoli ciuffi ai lati della testa. Durante la crescita sviluppa le zampe.\n\nCon la metamorfosi perde le branchie esterne e diventa un giovane tritone, che può lasciare l’acqua e trovare riparo in ambienti terrestri umidi. Gli adulti tornano negli stagni per riprodursi.\n\nLa cresta non compare in tutti gli adulti: è il maschio a svilupparla nel periodo riproduttivo. L’ultima illustrazione mostra proprio questo momento; le femmine non hanno la cresta dorsale. I disegni sono ingranditi per confrontare le fasi e non sono tutti nella stessa scala.","sources":[{"title":"LIFE AMPHICON — Tritone crestato italiano","url":"https://www.lifeamphicon.eu/italian-crested-newt-triturus-carnifex/"},{"title":"Froglife — Tritone crestato italiano","url":"https://www.froglife.org/info-advice/amphibians-and-reptiles/italian-crested-newt/"},{"title":"GIAPP — Bisana","url":"https://naturadipianura.it/luoghi/bisana/"}]}'::jsonb,area_description='Sulla riva destra del Reno, di fronte al Bosco della Panfilia, la Bisana conserva un paesaggio di golena in cui il fiume e il bosco si incontrano. L’area si estende per circa 65 ettari tra i territori di Galliera e Pieve di Cento ed è tutelata come Area di Riequilibrio Ecologico e sito della Rete Natura 2000.

Vicino all’acqua crescono soprattutto salici bianchi. Sui terrazzi più alti, formati dai depositi del fiume, il bosco si arricchisce di pioppi, aceri campestri, olmi e farnie. Sotto le chiome, biancospini, noccioli, prugnoli e altri arbusti offrono rifugi alla fauna.

Il percorso di visita attraversa i diversi ambienti e permette di osservare ciò che resta del paesaggio fluviale della pianura. Per conoscere la Bisana senza disturbare gli animali, resta sul tracciato e nelle piazzole dedicate alla visita.',area_url='https://naturadipianura.it/luoghi/bisana/' where day=12;
commit;
